// Cuánto tarda un dato en cruzar 8.422 km (Buenos Aires a Ashburn, círculo máximo)
const km = 8422;
const kmPorSegundoEnFibra = 299792.458 / 1.4682;
const propagacion = km / kmPorSegundoEnFibra * 1000;       // ms, no depende del ancho de banda
const transmision = (bytes, mbit) => bytes * 8 / (mbit * 1e6) * 1000;  // ms
console.log("propagación (ida): " + propagacion.toFixed(1) + " ms");
const casos = [["mensaje de chat (200 B)", 200], ["foto (3 MB)", 3e6], ["video (500 MB)", 500e6]];
for (const [nombre, bytes] of casos) {
  for (const mbit of [10, 1000]) {
    const t = transmision(bytes, mbit);
    console.log(nombre.padEnd(24) + String(mbit).padStart(5) + " Mbit/s: transmisión " + t.toFixed(2).padStart(10) + " ms | total " + (propagacion + t).toFixed(1).padStart(10) + " ms");
  }
}

// Modelo simplificado de una descarga TCP (sin pérdidas ni espera del servidor).
const MSS = 1460, IW = 10;            // bytes por segmento; ventana inicial de 10 segmentos (RFC 6928)
function descarga(bytes, mbit, rttMs) {
  const bw = mbit * 1e6 / 8;          // bytes por segundo
  const rtt = rttMs / 1000;
  let ventana = IW * MSS, resto = bytes, inicio = rtt / 2, rondas = 0;
  while (true) {
    const envio = Math.min(ventana, resto);
    const tx = envio / bw;
    rondas++;
    resto -= envio;
    if (resto <= 0) return { seg: inicio + tx + rtt / 2, rondas };
    inicio += Math.max(rtt, tx);      // la próxima ventana sale cuando vuelven los ACK
    ventana *= 2;                     // slow start: la ventana se duplica por viaje
  }
}
const tam = [[15e3, "15 KB"], [100e3, "100 KB"], [1e6, "1 MB"], [10e6, "10 MB"], [100e6, "100 MB"]];
for (const rtt of [20, 150]) {
  console.log(`\nRTT ${rtt} ms: segundos desde que sale el pedido hasta el último byte (ya con la conexión abierta)`);
  console.log("tamaño   |  10 Mbit/s | 100 Mbit/s |  1 Gbit/s");
  for (const [b, n] of tam) {
    const f = m => descarga(b, m, rtt).seg.toFixed(2).padStart(8);
    console.log(n.padEnd(8) + " | " + f(10) + "   | " + f(100) + "   | " + f(1000));
  }
}

// Producto ancho-retardo: cuántos bytes caben "en vuelo" entre emisor y receptor
const bdp = (mbit, rttMs) => (mbit * 1e6 / 8) * (rttMs / 1000);          // bytes
// Techo de velocidad si la ventana de recepción es de 65.535 bytes (sin escalado de ventana)
const techo = (rttMs) => 65535 * 8 / (rttMs / 1000) / 1e6;                // Mbit/s
const casos = [[100, 16, "100 Mbit/s, Buenos Aires - São Paulo"], [100, 82, "100 Mbit/s, Buenos Aires - Virginia"], [1000, 82, "1 Gbit/s, Buenos Aires - Virginia"], [1000, 150, "1 Gbit/s, RTT de 150 ms"]];
for (const [mbit, rtt, nombre] of casos) {
  console.log(nombre.padEnd(38) + "BDP = " + Math.round(bdp(mbit, rtt)).toLocaleString("en-US").padStart(11) + " B | techo con ventana de 64 KiB: " + techo(rtt).toFixed(1) + " Mbit/s");
}
